QJsonObject memory()
{
    rusage_info_v4 usage{};
    rusage rss{};
    const bool ok = proc_pid_rusage(getpid(), RUSAGE_INFO_V4,
        reinterpret_cast<rusage_info_t *>(&usage)) == 0;
    getrusage(RUSAGE_SELF, &rss);
    return {{"rusageV4Ok",ok}, {"residentBytes",double(usage.ri_resident_size)},
        {"physicalFootprintBytes",double(usage.ri_phys_footprint)},
        {"lifetimePeakPhysicalFootprintBytes",double(usage.ri_lifetime_max_phys_footprint)},
        {"peakResidentBytes",double(rss.ru_maxrss)}};
}
int main(int argc,char **argv)
{
    QApplication app(argc,argv);
    app.setOrganizationName("CoplandVerification");
    app.setApplicationName("CoplandUiBaseline20261012");
    app.setQuitOnLastWindowClosed(false);
    if (argc < 4) return 2;
    const QString root=QString::fromLocal8Bit(argv[1]);
    const QString binPath=QString::fromLocal8Bit(argv[2]);
    const QString output=QString::fromLocal8Bit(argv[3]);
    QJsonObject report{{"root",root},{"binPath",binPath},{"qtVersion",qVersion()},
        {"platform",QGuiApplication::platformName()}};
    QJsonArray stages;
    auto record=[&](const QString &name,qint64 elapsed=0,int count=-1) {
        QJsonObject r=memory();r["stage"]=name;r["elapsedMs"]=double(elapsed);
        if(count>=0)r["rows"]=count;
        stages.append(r);
    };
    record("process-start");
    MainWindow window(nullptr,MainWindow::StartupMode::UiOnly);
    window.show();
    QApplication::processEvents();
    window.grab();
    auto *model=window.findChild<MediaTableModel *>();
    auto *proxy=window.findChild<MediaFilterProxy *>();
    auto *scanner=window.findChild<MediaScanner *>();
    auto *ops=window.findChild<FileOperationController *>();
    auto *table=window.findChild<QTableView *>();
    if(!model||!proxy||!scanner||!ops||!table)return 3;
    record("window-initialised");
    const QStringList roots{root};
    if(!QMetaObject::invokeMethod(&window,"onPathsDropped",Qt::DirectConnection,Q_ARG(QStringList,roots)))return 4;
    auto scan=[&](const QString &name) {
        QEventLoop loop;
        bool done=false,failed=false;
        QMetaObject::invokeMethod(&window,"onPathsDropped",Qt::DirectConnection,Q_ARG(QStringList,roots));
        QElapsedTimer timer; timer.start();
        auto conn=QObject::connect(scanner,&MediaScanner::scanFinished,&window,
            [&](const QVector<MediaFile> &) {done=true;loop.quit();},Qt::QueuedConnection);
        auto fail=QObject::connect(scanner,&MediaScanner::scanFailed,&window,
            [&](const QString &e){report["error"]=e;failed=true;loop.quit();},Qt::QueuedConnection);
        QTimer timeout; timeout.setSingleShot(true);
        QObject::connect(&timeout,&QTimer::timeout,&loop,[&]{failed=true;scanner->cancelScan();loop.quit();});
        timeout.start(60000);
        QMetaObject::invokeMethod(&window,"scanSelected",Qt::DirectConnection);
        if(ops->isIdle())return false;
        loop.exec();
        QObject::disconnect(conn);QObject::disconnect(fail);
        if(!done||failed)return false;
        QApplication::processEvents();
        const auto pixmap=window.grab();
        if(pixmap.isNull()||!ops->isIdle()||model->rowCount()!=proxy->rowCount())return false;
        record(name,timer.elapsed(),model->rowCount());
        return true;
    };
    if(!scan("scan-1-through-offscreen-paint"))return 5;
    const int firstCount=model->rowCount();
    QJsonObject outcomes;
    int captured=0;
    for(const auto &row:model->allFiles()) {
        const auto key=QString::number(int(row.metadataStatus.headerOutcome));
        outcomes[key]=outcomes[key].toInt()+1;
        captured+=row.operationScanReceipt.has_value();
    }
    report["headerOutcomeCounts"]=outcomes;
    report["rowsWithOperationReceipt"]=captured;
    qint64 totalBytes=0;for(const auto &row:model->allFiles())totalBytes+=row.sizeBytes;
    report["totalPhysicalBytes"]=double(totalBytes);
    QElapsedTimer timer;timer.start();
    proxy->sort(int(MediaTableModel::Column::SizeMB),Qt::DescendingOrder);
    QApplication::processEvents();window.grab();
    record("sort-size",timer.elapsed(),proxy->rowCount());
    timer.restart();
    QMetaObject::invokeMethod(&window,"onSearchChanged",Qt::DirectConnection,Q_ARG(QString,QString("Audio")));
    QApplication::processEvents();window.grab();
    record("search-audio",timer.elapsed(),proxy->rowCount());
    QMetaObject::invokeMethod(&window,"onSearchChanged",Qt::DirectConnection,Q_ARG(QString,QString()));
    QVector<MediaFile> snapshot;
    snapshot.reserve(proxy->rowCount());
    for(int i=0;i<proxy->rowCount();++i)snapshot.append(model->fileAt(proxy->mapToSource(proxy->index(i,0)).row()));
    timer.restart();
    const bool csvOk=MediaCsv::write(output+".csv",snapshot,{model->precomputesEnabled()});
    report["csvWritten"]=csvOk;
    record("csv-visible-frozen-rows",timer.elapsed(),snapshot.size());
    // Keep only one frozen export row; test ownership independently of allocator release.
    snapshot=snapshot.isEmpty()?QVector<MediaFile>{}:QVector<MediaFile>{snapshot.first()};
    timer.restart();
    QVector<AvbBin> bins{AvbBinLoader::load(binPath)};
    report["binUsable"]=bins.first().isUsable();
    report["binFullFileIds"]=bins.first().mediaFileIds.fullIds.size();
    report["binCoverageComplete"]=bins.first().coverageComplete;
    report["binWarnings"]=QJsonArray::fromStringList(bins.first().warnings);
    AvbFilter filter;AvbFilter::Step step;
    step.fileReferences=bins.first().mediaFileIds;
    step.binDisplayNames.append(bins.first().displayName);
    filter.steps.append(step);proxy->setBinFilter(filter);
    QApplication::processEvents();window.grab();
    record("bin-load-model-apply-filter-paint",timer.elapsed(),proxy->rowCount());
    proxy->setBinFilter({});bins.clear();filter={};step={};
    QApplication::processEvents();record("bin-references-released",0,proxy->rowCount());
    if(!scan("rescan-through-offscreen-paint"))return 6;
    report["sameRowCountAfterRescan"]=model->rowCount()==firstCount;
    report["frozenRowStillUsable"]=snapshot.isEmpty() || !MediaCsv::rowLine(snapshot.first()).isEmpty();
    report["scanOwnershipCheck"]="No scan/session owner in compact rows; weak-pointer comparison is inapplicable.";
    snapshot.clear();QApplication::processEvents();
    record("snapshot-released",0,model->rowCount());
    model->setMediaFiles({});QApplication::processEvents();record("table-cleared");
    report["stages"]=stages;
    QFile file(output); if(!file.open(QIODevice::WriteOnly))return 7;
    file.write(QJsonDocument(report).toJson());
    return csvOk?0:8;
}

