namespace
{
	QByteArray readBytes(const QString &path)
	{
		QFile file(path);
		return file.open(QIODevice::ReadOnly) ? file.readAll() : QByteArray{};
	}

	bool waitUntil(const std::function<bool()> &ready, int timeoutMs = 15000)
	{
		if (ready())
			return true;
		QEventLoop loop;
		QTimer poll, timeout;
		poll.setInterval(10);
		timeout.setSingleShot(true);
		QObject::connect(&poll, &QTimer::timeout, &loop, [&]
			{ if (ready()) loop.quit(); });
		QObject::connect(&timeout, &QTimer::timeout, &loop, &QEventLoop::quit);
		poll.start();
		timeout.start(timeoutMs);
		loop.exec();
		return ready();
	}

	using Values = QMap<QString, QStringList>;
	Values retainedValues(MediaTableModel &model)
	{
		Values result;
		for (int row = 0; row < model.rowCount(); ++row)
		{
			QStringList values;
			for (int column = 0; column < model.columnCount(); ++column)
				if (column != int(MediaTableModel::Column::KelpieId))
					values.append(model.index(row, column).data(Qt::DisplayRole).toString());
			auto file = model.fileAt(row);
			file.kelpieId = 0; // Session identity is deliberately excluded from rescan equality.
			values.append(MediaCsv::rowLine(file, {model.precomputesEnabled()}));
			result.insert(file.mediaFilePath, values);
		}
		return result;
	}

	QJsonObject jsonValues(const Values &values)
	{
		QJsonObject result;
		for (auto it = values.cbegin(); it != values.cend(); ++it)
			result.insert(it.key(), QJsonArray::fromStringList(it.value()));
		return result;
	}
}

int main(int argc, char **argv)
{
	QApplication::setAttribute(Qt::AA_DontUseNativeDialogs);
	QApplication app(argc, argv);
	app.setOrganizationName(QStringLiteral("CoplandVerification"));
	app.setApplicationName(QStringLiteral("CoplandNativeWorkflow20261018"));
	app.setApplicationVersion(QStringLiteral("0.0.2"));
	app.setQuitOnLastWindowClosed(false);
	if (argc != 4)
		return 2; // root, copied matching bin, fresh output JSON path.
	const QString root = QString::fromLocal8Bit(argv[1]);
	const QString binPath = QString::fromLocal8Bit(argv[2]);
	const QString output = QString::fromLocal8Bit(argv[3]);
	const QString csvPath = output + QStringLiteral(".csv");
	if (QFile::exists(output)) return 4;
	QJsonObject report{{"root", root}, {"binPath", binPath}, {"platform", QGuiApplication::platformName()},
		{"qtVersion", qVersion()}, {"scope", "Supplemental native-window workflow; no historical native timing comparison"}};
	QJsonObject checks;
	QJsonArray stages;
	int exitCode = 0;
	try
	{
		const auto require = [&](bool condition, const QString &name)
		{
			checks.insert(name, condition);
			if (!condition)
				throw std::runtime_error(name.toStdString());
		};
		require(QGuiApplication::platformName() == QStringLiteral("cocoa"), QStringLiteral("cocoaPlatform"));
		require(!QFile::exists(output) && !QFile::exists(csvPath), QStringLiteral("freshOutputPaths"));
		const QByteArray binHash = QCryptographicHash::hash(readBytes(binPath), QCryptographicHash::Sha256).toHex();
		report.insert("binSha256", QString::fromLatin1(binHash));
		require(binHash == "330a9a135f0682a561d91bff10316aceefade6f0474c059ad856f8024ac7a8aa", QStringLiteral("genuineMatchingBinHash"));
		Diagnostics::install(QFileInfo(output).absolutePath() + QStringLiteral("/native-diagnostics"));
		report.insert("diagnosticLog", Diagnostics::logPath());
		MainWindow window(nullptr, MainWindow::StartupMode::UiOnly);
		window.show();
		QApplication::processEvents();
		auto *model = window.findChild<MediaTableModel *>();
		auto *proxy = window.findChild<MediaFilterProxy *>();
		auto *scanner = window.findChild<MediaScanner *>();
		auto *ops = window.findChild<FileOperationController *>();
		auto *table = window.findChild<QTableView *>();
		auto *console = window.findChild<QPlainTextEdit *>();
		require(model && proxy && scanner && ops && table && console, QStringLiteral("productionWidgetsPresent"));
		const auto scan = [&](const QString &stage)
		{
			const QStringList paths{root};
			QMetaObject::invokeMethod(&window, "onPathsDropped", Qt::DirectConnection, Q_ARG(QStringList, paths));
			bool done = false;
			QString failure;
			const auto completed = QObject::connect(scanner, &MediaScanner::scanFinished, &window,
				[&](const QVector<MediaFile> &) { done = true; }, Qt::QueuedConnection);
			const auto failed = QObject::connect(scanner, &MediaScanner::scanFailed, &window,
				[&](const QString &message)
				{
					failure = message;
					if (auto *dialog = qobject_cast<QDialog *>(QApplication::activeModalWidget()))
						dialog->reject();
				}, Qt::QueuedConnection);
			QElapsedTimer timer;
			timer.start();
			const bool invoked = QMetaObject::invokeMethod(&window, "scanSelected", Qt::DirectConnection);
			const bool settled = invoked && waitUntil([&] { return done || !failure.isEmpty(); }, 60000);
			QObject::disconnect(completed);
			QObject::disconnect(failed);
			if (!settled)
				scanner->cancelScan();
			require(settled && done && failure.isEmpty(), stage + QStringLiteral("Completed"));
			QApplication::processEvents();
			require(!window.grab().isNull() && ops->isIdle() && model->rowCount() == proxy->rowCount(), stage + QStringLiteral("ReadyForTable"));
			stages.append(QJsonObject{{"stage", stage}, {"elapsedMs", timer.elapsed()}, {"rows", model->rowCount()}});
		};
		scan(QStringLiteral("scanThroughNativeWindowPaint"));
		const auto before = retainedValues(*model);
		require(model->rowCount() == 267 && before.size() == 267, QStringLiteral("complete267RowInventory"));
		QString expectedPath, expectedFileMobId;
		for (const auto &file : model->allFiles())
			if (file.fileName == QStringLiteral("TONE_100A01.1DAFE820.612550.mxf"))
			{
				require(expectedPath.isEmpty(), QStringLiteral("uniqueExpectedPhysicalFile"));
				expectedPath = file.mediaFilePath;
				expectedFileMobId = file.fileMobId;
			}
		require(!expectedPath.isEmpty() && !expectedFileMobId.isEmpty(), QStringLiteral("expectedToneInInventory"));
		report.insert("expectedPhysicalPath", expectedPath);
		report.insert("expectedFileMobId", expectedFileMobId);
		QMetaObject::invokeMethod(&window, "onFilterByBins", Qt::DirectConnection);
		auto *dialog = window.findChild<AvbFilterDialog *>();
		require(dialog, QStringLiteral("actualBinDialogOpened"));
		bool loaded = false, applied = false;
		AvbBin bin;
		QObject::connect(dialog, &AvbFilterDialog::binLoaded, &window, [&](const AvbBin &value) { bin = value; loaded = true; });
		QObject::connect(dialog, &AvbFilterDialog::filterChainChanged, &window,
			[&](const AvbFilter &filter, const QStringList &) { applied = filter.isActive(); });
		QElapsedTimer binTimer;
		binTimer.start();
		dialog->addBinFromFile(binPath);
		require(waitUntil([&] { return loaded && applied && proxy->rowCount() > 0; }), QStringLiteral("actualBinFilterApplied"));
		require(bin.isUsable() && bin.mediaFileIds.matches(AvbFileId::fromMobId(expectedFileMobId)), QStringLiteral("genuineBinReferencesExpectedFile"));
		require(proxy->rowCount() == 1, QStringLiteral("oneMatchingPhysicalRow"));
		const auto &visible = model->fileAt(proxy->mapToSource(proxy->index(0, 0)).row());
		require(visible.mediaFilePath == expectedPath && visible.fileMobId == expectedFileMobId, QStringLiteral("expectedToneIsVisible"));
		require(retainedValues(*model) == before, QStringLiteral("binLoadingPreservesAllPreparedDisplayValues"));
		report.insert("binCoverageComplete", bin.coverageComplete);
		report.insert("binWarnings", QJsonArray::fromStringList(bin.warnings));
		stages.append(QJsonObject{{"stage", "actualBinLoadAndFilter"}, {"elapsedMs", binTimer.elapsed()}, {"rows", proxy->rowCount()}});
		dialog->hide();
		window.raise();
		window.activateWindow();
		QApplication::processEvents();
		report.insert("filteredScreenshotSaved", window.grab().save(output + QStringLiteral(".png")));
		table->clearSelection();
		const MediaCsv::Options options{model->precomputesEnabled()};
		const QByteArray expectedCsv = QByteArray::fromHex("efbbbf") + MediaCsv::headerLine(options).toUtf8() + MediaCsv::rowLine(visible, options).toUtf8();
		bool sawSave = false, pickerAccepted = false, pickerTimedOut = false;
		QElapsedTimer exportTimer;
		exportTimer.start();
		QTimer picker;
		picker.setInterval(20);
		QObject::connect(&picker, &QTimer::timeout, &window, [&]
		{
			auto *modal = QApplication::activeModalWidget();
			if (exportTimer.elapsed() > 15000)
			{
				pickerTimedOut = true;
				if (auto *active = qobject_cast<QDialog *>(modal)) active->reject();
				return;
			}
			if (auto *save = qobject_cast<QFileDialog *>(modal); save && !sawSave)
			{
				sawSave = true;
				save->setDirectory(QFileInfo(csvPath).absolutePath());
				auto *editor = save->findChild<QLineEdit *>(QStringLiteral("fileNameEdit"));
				if (!editor) { save->reject(); return; }
				editor->setFocus();
				editor->setText(QFileInfo(csvPath).fileName());
				pickerAccepted = save->selectedFiles() == QStringList{csvPath};
				if (pickerAccepted) QMetaObject::invokeMethod(save, "accept", Qt::DirectConnection);
				else save->reject();
			}
			else if (auto *message = qobject_cast<QMessageBox *>(modal)) message->reject();
		});
		picker.start();
		const bool exported = QMetaObject::invokeMethod(&window, "onExportCsv", Qt::DirectConnection);
		picker.stop();
		require(exported && sawSave && pickerAccepted && !pickerTimedOut, QStringLiteral("actualExportSaveDialogAccepted"));
		require(readBytes(csvPath) == expectedCsv, QStringLiteral("actualExportBytesMatchVisibleRow"));
		const QString confirmation = QStringLiteral("CSV export complete: 1 visible rows to %1.").arg(csvPath);
		require(console->toPlainText().count(confirmation) == 1, QStringLiteral("consoleConfirmsSavedPathAndRowCount"));
		require(QString::fromUtf8(readBytes(Diagnostics::logPath())).contains(confirmation), QStringLiteral("diskLogConfirmsExport"));
		report.insert("csvPath", csvPath);
		report.insert("csvSha256", QString::fromLatin1(QCryptographicHash::hash(expectedCsv, QCryptographicHash::Sha256).toHex()));
		report.insert("consoleConfirmation", confirmation);
		stages.append(QJsonObject{{"stage", "actualExportDialogAndWrite"}, {"elapsedMs", exportTimer.elapsed()}, {"rows", 1}});
		dialog->clearFilterSteps();
		require(waitUntil([&] { return !applied && proxy->rowCount() == 267; }), QStringLiteral("publicClearFilterRestoresInventory"));
		scan(QStringLiteral("rescanThroughNativeWindowPaint"));
		require(retainedValues(*model) == before, QStringLiteral("rescanPreservesInventoryAndDisplayValues"));
		auto *bins = dialog->findChild<QListWidget *>(QStringLiteral("BinList"));
		require(bins && bins->count() == 1 && proxy->rowCount() == 267, QStringLiteral("rescanKeepsBinLoadedAndFiltersClear"));
		report.insert("retainedDisplayValues", jsonValues(before));
		report.insert("comparisonExcludes", "Session-local KelpieId only; all other table display columns and CSV values checked");
	}
	catch (const std::exception &error)
	{
		exitCode = 1;
		report.insert("error", QString::fromUtf8(error.what()));
	}
	checks.insert("passed", exitCode == 0);
	report.insert("checks", checks);
	report.insert("stages", stages);
	QFile result(output);
	if (!result.open(QIODevice::WriteOnly)) return 3;
	result.write(QJsonDocument(report).toJson());
	return exitCode;
}

